function dataDiskMapForm(params) {
  // Async (CMP registers it with isAsync). Watches the order form for a disk_map
  // parameter, which an environment panel adds when the environment has it, hides
  // its text box, and puts a Data Disks table in its place. Every table change is
  // written back to disk_map as a JSON list of disks, which is what the form
  // submits. The columns follow the panel's OS build: drive letters for Windows,
  // mount points for Linux, both when the build's name does not say which.
  var survey = this.survey;
  var done = this.returnResult.bind(this);
  if (!survey) { done("error: no survey instance is available to the form function."); return; }
  if (survey.cbDiskMapTables) { done("ready"); return; }
  var tables = {};
  survey.cbDiskMapTables = tables;

  var LETTERS = "DEFGHIJKLMNOPQRSTUVWXYZ".split("");
  var MOUNTS = ["/u01", "/u02", "/u03", "/u04", "/data", "/app", "/backup"];
  var RESERVED = ["/bin", "/boot", "/dev", "/etc", "/lib", "/lib64", "/proc", "/root", "/run", "/sbin", "/sys", "/tmp", "/usr", "/var"];
  var MOUNT_RE = /^(\/[A-Za-z0-9._-]+)+$/;
  var WINDOWS_NAME_RE = /^[A-Za-z0-9][A-Za-z0-9 _-]{0,31}$/;
  var LINUX_NAME_RE = /^[A-Za-z][A-Za-z0-9_]{0,11}$/;

  function isDiskMap(q) {
    return q && q.getType && q.getType() === "comment" && /(^|\.)disk_map$/.test(String(q.name));
  }

  function prefix(source) { return String(source.name).split(".")[0]; }

  // "windows", "linux", or "" when the panel has no OS build or its name is unclear.
  function osOf(source) {
    var build = survey.getQuestionByName(prefix(source) + ".osBuild");
    if (!build || build.isEmpty()) return "";
    var text = String(build.displayValue || "");
    if (/windows/i.test(text)) return "windows";
    if (/linux|oracle|rhel|red hat|centos|rocky|alma|\bol ?\d/i.test(text)) return "linux";
    return "";
  }

  function columns(os) {
    var cols = [];
    if (os !== "linux") {
      cols.push({ name: "drive_letter", title: os ? "Drive Letter" : "Drive Letter (Windows)", cellType: "dropdown", choices: LETTERS, isRequired: os === "windows" });
    }
    if (os !== "windows") {
      cols.push({ name: "mount_point", title: os ? "Mount Point" : "Mount Point (Linux)", cellType: "text", placeholder: "/u01", dataList: MOUNTS, isRequired: os === "linux" });
    }
    cols.push({ name: "size_gb", title: "Size (GB)", cellType: "text", inputType: "number", min: 1, max: 16384, isRequired: true });
    cols.push({ name: "volume_name", title: "Volume Name", cellType: "text", maxLength: os === "linux" ? 12 : 32, isRequired: true });
    return cols;
  }

  function description(os) {
    var text = "One row per disk. CloudBolt adds the disks to the VM in this order and records where the hypervisor put each one, so the guest script prepares the right disk. ";
    if (os === "windows") return text + "Each disk gets its drive letter and an NTFS volume labeled with the volume name (up to 32 characters).";
    if (os === "linux") return text + "Each disk becomes volume group vg_ and logical volume lv_ plus the volume name (up to 12 letters, digits or underscores), formatted XFS and mounted at its mount point.";
    return text + "Windows servers use the drive letter and Linux servers the mount point; fill in the one for your OS build, or both. Linux volume names are up to 12 letters, digits or underscores.";
  }

  function seedRows(value) {
    var rows = value;
    if (!rows) return [];
    if (typeof rows === "string") {
      try { rows = JSON.parse(rows); } catch (e) { return []; }
    }
    if (!Array.isArray(rows)) rows = [rows];
    return rows.filter(function (r) { return r && typeof r === "object"; });
  }

  function text(value) { return value === undefined || value === null ? "" : String(value).trim(); }

  // The table's rows as disk_map entries, keeping only the target columns shown.
  function disks(entry) {
    var out = [];
    (entry.table.value || []).forEach(function (r) {
      if (!r) return;
      var d = {};
      if (entry.os !== "linux" && text(r.drive_letter)) d.drive_letter = text(r.drive_letter).toUpperCase();
      if (entry.os !== "windows" && text(r.mount_point)) d.mount_point = text(r.mount_point);
      if (text(r.size_gb)) d.size_gb = /^[0-9]+$/.test(text(r.size_gb)) ? parseInt(text(r.size_gb), 10) : text(r.size_gb);
      if (text(r.volume_name)) d.volume_name = text(r.volume_name);
      if (Object.keys(d).length) out.push(d);
    });
    return out;
  }

  function sync(entry) {
    var list = disks(entry);
    if (list.length) { entry.source.value = JSON.stringify(list); } else { entry.source.clearValue(); }
  }

  // The first problem with the table's rows, or "" when there is none.
  function problem(entry) {
    var os = entry.os;
    var letters = {}, names = {}, mounts = [];
    var rows = entry.table.value || [];
    for (var i = 0; i < rows.length; i++) {
      var r = rows[i] || {};
      var n = "Disk " + (i + 1) + ": ";
      var letter = os !== "linux" ? text(r.drive_letter).toUpperCase() : "";
      var mount = os !== "windows" ? text(r.mount_point).replace(/(.)\/+$/, "$1") : "";
      var name = text(r.volume_name);
      var size = text(r.size_gb);
      if (!/^[0-9]+$/.test(size) || +size < 1 || +size > 16384) return n + "enter a whole number of GB from 1 to 16384.";
      if (os === "windows" && !letter) return n + "choose a drive letter.";
      if (os === "linux" && !mount) return n + "enter a mount point.";
      if (!os && !letter && !mount) return n + "enter a drive letter (Windows) or a mount point (Linux).";
      if (letter) {
        if (letters[letter]) return n + "drive letter " + letter + ": is already used by another disk.";
        letters[letter] = true;
        if (!WINDOWS_NAME_RE.test(name)) return n + "a Windows volume name is 1 to 32 letters, digits, spaces, hyphens or underscores, starting with a letter or digit.";
      }
      if (mount) {
        if (!MOUNT_RE.test(mount) || /\/\.\.?(\/|$)/.test(mount)) return n + "enter the mount point as an absolute path such as /u01.";
        if (RESERVED.indexOf(mount) >= 0 || /^\/(boot|dev|proc|run|sys)\//.test(mount)) return n + mount + " is an operating system directory.";
        for (var j = 0; j < mounts.length; j++) {
          var other = mounts[j];
          if (mount === other || mount.indexOf(other + "/") === 0 || other.indexOf(mount + "/") === 0) return n + "mount point " + mount + " overlaps " + other + ".";
        }
        mounts.push(mount);
        if (!LINUX_NAME_RE.test(name)) return n + "a Linux volume name is 1 to 12 letters, digits or underscores, starting with a letter.";
        if (names[name.toLowerCase()]) return n + "volume name " + name + " is already used by another disk.";
        names[name.toLowerCase()] = true;
      }
    }
    return "";
  }

  function shape(entry) {
    entry.table.fromJSON({ columns: columns(entry.os) });
    entry.table.description = description(entry.os);
  }

  function transform(source) {
    if (!isDiskMap(source) || source.cbDiskMapTable || !source.parent || !source.parent.addNewQuestion) return;
    var panel = source.parent;
    // Not named <tier>.<something>, so the submit does not treat it as a parameter.
    var name = "cb_disk_map_rows_" + prefix(source);
    var table = panel.addNewQuestion("matrixdynamic", name, panel.elements.indexOf(source) + 1);
    var entry = { source: source, table: table, os: osOf(source) };
    source.cbDiskMapTable = table;
    tables[name] = entry;
    table.fromJSON({
      title: source.title || "Data Disks",
      isRequired: !!source.isRequired,
      addRowText: "Add disk",
      removeRowText: "Remove",
      titleLocation: "top"
    });
    table.rowCount = source.isRequired ? 1 : 0;
    table.minRowCount = source.isRequired ? 1 : 0;
    shape(entry);
    var seed = seedRows(source.value);
    if (seed.length) table.value = seed;
    source.visible = false;
    sync(entry);
  }

  function scan() {
    survey.getAllQuestions().forEach(transform);
    Object.keys(tables).forEach(function (name) {
      var entry = tables[name];
      if (survey.getQuestionByName(name) !== entry.table) { delete tables[name]; return; }
      var os = osOf(entry.source);
      if (os !== entry.os) { entry.os = os; shape(entry); sync(entry); }
    });
  }

  survey.onValueChanged.add(function (sender, options) {
    var entry = tables[options.name];
    if (entry && entry.table === options.question) sync(entry);
    else if (/\.osBuild$/.test(options.name)) scan();
  });
  survey.onValidateQuestion.add(function (sender, options) {
    var entry = tables[options.name];
    if (!entry || entry.table !== options.question) return;
    var error = problem(entry);
    if (error) options.error = error;
  });
  // Environment panels are rebuilt with panel.fromJSON; transform after it returns.
  survey.onQuestionAdded.add(function () { setTimeout(scan, 0); });
  setInterval(scan, 750);
  scan();
  done("ready");
}
